fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "--"

    val seconds = exposureTimeNs / 1_000_000_000.0

    // Slow shutter (>= 0.5s): show as (fractional) seconds, e.g. "0.5s", "1s", "2.5s"
    if (seconds >= 0.5) {
        val value = if (seconds.toLong().toDouble() == seconds) {
            "${seconds.toLong()}"
        } else {
            String.format(java.util.Locale.US, "%.2f", seconds).trimEnd('0').trimEnd('.')
        }
        return "${value}s"
    }

    // Fast shutter: show as reciprocal, e.g. "1/30s", "1/1000s"
    val denominator = (1.0 / seconds).roundToInt()
    return "1/${denominator}s"
}

