import sys

def find_comment_start(line):
    i, n = 0, len(line)
    in_str = in_char = False
    while i < n:
        c = line[i]
        if in_str:
            if c == '\\':
                i += 2
                continue
            if c == '"':
                in_str = False
            i += 1
            continue
        if in_char:
            if c == '\\':
                i += 2
                continue
            if c == "'":
                in_char = False
            i += 1
            continue
        if c == '"':
            in_str = True
            i += 1
            continue
        if c == "'":
            in_char = True
            i += 1
            continue
        if c == '/' and i + 1 < n and line[i + 1] == '/':
            return i
        i += 1
    return None

def expected_clean(line):
    """Return (keep: bool, cleaned: str) for a single original line."""
    pos = find_comment_start(line)
    if pos is None:
        return True, line
    code = line[:pos].rstrip()
    if code.strip() == '':
        return False, ''
    return True, code

orig = open('/tmp/opencode/source.kt.bak', encoding='utf-8').read().split('\n')
clean = open('/tmp/opencode/source.clean.kt', encoding='utf-8').read().split('\n')

